from __future__ import annotations
import json,re,unicodedata
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'reading/arabic/b2/passages.jsonl'
LEX=ROOT/'reading/lexicons/arabic.jsonl'
AR_DIAC=re.compile(r'[\u0610-\u061a\u064b-\u065f\u0670\u06d6-\u06ed]')
def norm(s):return AR_DIAC.sub('',unicodedata.normalize('NFC',s).replace('ـ','').strip())
def lexicon():
 d={}
 for line in LEX.read_text(encoding='utf-8').splitlines():
  if line.strip():
   r=json.loads(line);d.setdefault(norm(r.get('form','')),r)
 return d
PREFERRED={'باحث':'researcher','بنية':'structure','معدات':'equipment','حشرة':'insect','مراقبة':'monitoring','مورد':'resource','تمويل':'funding','كمية':'quantity; amount','إمكانية':'possibility','مبدأ':'principle'}
def target(f,text,d):
 r=d.get(norm(f))
 if not r:raise KeyError(f)
 return {'id':f"ar-r{r['rank']}",'form':f,'lemma':f,'part_of_speech':r.get('part_of_speech_source'),'intended_sense':PREFERRED[f],'register':'contemporary standard','variety':'MSA','context_strategy':['evidence_interpretation','counterargument','cause_consequence'],'first_introduced':True,'exposures_in_text':max(1,text.count(f)),'source_lexicon':r.get('source_file'),'source_rank':r['rank'],'beyond_base':False}
def qa(items):
 q=[];a=[]
 for i,(t,p,x,ids) in enumerate(items,1):
  z={'id':f'q{i}','type':t,'prompt':p,'answer_id':f'a{i}'}
  if ids:z['target_ids']=ids
  q.append(z);a.append({'id':f'a{i}','question_id':f'q{i}','answer':x,'explanation':''})
 if len(q)!=10:raise ValueError('ten questions required')
 return q,a
R=[
{'id':'ar-b2-u01-p01','sequence':1,'title':'النموذج الذي نجح لأنه كان أبسط من الواقع','passage_type':'instructional','genre':'popular-science explanation','domains':['science','education','society'],'topics':['models','structure','research interpretation'],'text':'في ورشة مدرسية خيالية عرض باحث نموذجًا بسيطًا يوضح كيف تنتقل حركة بين أجزاء مترابطة. كانت بنية النموذج واضحة: ثلاث قطع فقط، وكل قطعة تؤثر في التالية. بعد العرض قال أحد الطلاب إن النموذج «يثبت» أن النظام الحقيقي يعمل بالطريقة نفسها. توقف الباحث عند كلمة يثبت. قال إن فائدة النموذج جاءت تحديدًا من أنه حذف كثيرًا من التفاصيل. لو حاول تمثيل كل جزء في الواقع، لصعب أن نرى العلاقة التي يريد شرحها. لكن الحذف نفسه يضع حدًا على الاستنتاج. النموذج يساعدنا على اختبار فكرة محددة: ماذا يحدث داخل هذه البنية إذا تغير عنصر واحد وبقيت الافتراضات الأخرى ثابتة؟ أما النظام الحقيقي فقد يحتوي على عناصر إضافية وعلاقات لا تظهر هنا. اقترح الباحث مقارنة النموذج بملاحظات من حالات مختلفة، والبحث خصوصًا عن الحالات التي يفشل فيها التوقع. قال إن النموذج الجيد ليس صورة مصغرة يجب أن تطابق الواقع في كل شيء، ولا لعبة بلا قيمة لأنها مبسطة. هو أداة تفكير: يوضح بعض العلاقات مقابل تجاهل علاقات أخرى. وتصبح المسألة العلمية والاجتماعية معًا عندما نستخدم نتيجة النموذج لاتخاذ قرار خارج المختبر؛ حينها يجب أن نسأل أي أجزاء من الواقع أزيلت، وهل قد تكون مهمة للناس الذين سيتأثرون بالقرار.','target_forms':['باحث','بنية'],'reviews':[{'id':'ar-r1314','form':'نموذج','review_stage':'R3','representation':'running_text'},{'id':'ar-r909','form':'دليل','review_stage':'R5','representation':'other'}],'grammar':[{'id':'ar-b2-model-scope','role':'new','description':'فائدة التبسيط نفسها تضع حدًا على الاستنتاج'}],'discourse':[{'id':'b2-model-to-decision','role':'new','description':'move from model usefulness to model limits and then to social consequences of applying it'}],'qa':[('gist','ما الفكرة الأساسية عن النماذج؟','تبسيط النموذج يجعله مفيدًا لفحص علاقة محددة، لكنه يمنع معاملته كنسخة كاملة من الواقع.',None),('literal_detail','كم قطعة يحتوي النموذج الخيالي؟','ثلاث قطع.',None),('inference','لماذا يطلب الباحث البحث عن الحالات التي يفشل فيها التوقع؟','لأن الفشل يكشف حدود الافتراضات والعلاقات التي لا يمثلها النموذج.',None),('cause_effect','كيف يؤدي حذف التفاصيل إلى فائدتين متعارضتين ظاهريًا؟','يجعل العلاقة الأساسية أوضح، لكنه يقلل نطاق ما يمكن استنتاجه عن النظام الحقيقي.',None),('main_claim','متى تصبح حدود النموذج قضية اجتماعية أيضًا؟','عندما تستخدم نتائجه في قرار يؤثر في أشخاص أو ظروف لم يمثلها النموذج بالكامل.',None),('argument_relation','ما وظيفة رفض الخيارين «صورة مصغرة كاملة» و«لعبة بلا قيمة»؟','يضع موقفًا وسطًا يرى النموذج أداة مفيدة ومحدودة في الوقت نفسه.',None),('contrast','ما الفرق بين سؤال داخل النموذج وسؤال عن الواقع؟','الأول يعمل تحت افتراضات محددة وثابتة، والثاني قد يتضمن عناصر وعلاقات لم تدخل النموذج.',None),('reference_resolution','إلى ماذا تشير «الحذف نفسه»؟','إلى حذف النموذج كثيرًا من تفاصيل النظام الحقيقي.',None),('single_word_definition','ما معنى «باحث»؟','شخص يجمع الأدلة ويدرس سؤالًا بطريقة منظمة للوصول إلى معرفة جديدة أو أدق.', ['ar-r1271']),('single_word_definition','ما معنى «بنية»؟','تركيب الشيء وطريقة ارتباط أجزائه بعضها ببعض.', ['ar-r1373'])]},
{'id':'ar-b2-u01-p02','sequence':2,'title':'صور كثيرة لا تعني مراقبة متوازنة','passage_type':'reinforcement','genre':'citizen-science case analysis','domains':['science','community','technology'],'topics':['observation','sampling','insects','monitoring'],'text':'صمم فريق خيالي مشروعًا مجتمعيًا لتسجيل أنواع الحشرات التي يراها السكان في الحدائق. لم يحتج المشاركون إلى معدات معقدة؛ يكفي هاتف وصورة ومكان تقريبي للمشاهدة. خلال أسابيع وصلت آلاف الصور، ففرح الفريق بحجم المشاركة. لكن الباحثة المسؤولة عن التحليل لاحظت أن معظم الصور جاءت من حدائق قريبة من وسط المدينة وفي عطلات نهاية الأسبوع. كما أن بعض أنواع الحشرات الملونة جذبت التصوير أكثر من الأنواع الصغيرة أو التي تظهر ليلًا. لذلك حذرت من تحويل عدد الصور مباشرة إلى تقدير لعدد كل حشرة في المنطقة. المشروع ممتاز للمراقبة الواسعة واكتشاف أماكن تستحق دراسة إضافية، لكنه لا يضمن أن كل مكان وكل وقت وكل نوع يملك فرصة متساوية للظهور في البيانات. اقترح الفريق مرحلة ثانية: اختيار مواقع محددة مسبقًا، وزيارتها في أوقات ثابتة، وتسجيل عدم رؤية الحشرات أيضًا بدل إرسال الصور الناجحة فقط. لم يلغوا البيانات الأولى؛ استخدموها لسؤال مختلف. قالت الباحثة إن كثرة الملاحظات لا تعالج تلقائيًا انحياز طريقة جمعها. أحيانًا نحتاج إلى عدد أقل من الملاحظات المنظمة كي نجيب عن سؤال لا تستطيع مجموعة ضخمة وغير متوازنة الإجابة عنه بثقة.','target_forms':['معدات','حشرة','مراقبة'],'reviews':[{'id':'ar-r1340','form':'متعدد','review_stage':'R3','representation':'other'},{'id':'ar-r1353','form':'مؤشر','review_stage':'R3','representation':'other'}],'grammar':[{'id':'ar-b2-many-data-biased','role':'new','description':'كثرة الملاحظات لا تعالج تلقائيًا انحياز طريقة جمعها'}],'discourse':[{'id':'b2-observation-sampling','role':'new','description':'distinguish participation volume from balanced observation and redesign sampling for a different question'}],'qa':[('gist','لماذا لا يمكن استخدام عدد الصور مباشرة لتقدير عدد الحشرات؟','لأن مواقع وأوقات وأنواع المشاهدة غير متوازنة واحتمال التصوير يختلف بينها.',None),('literal_detail','ما الذي تحتاجه المشاركة الأساسية؟','هاتف وصورة ومكان تقريبي للمشاهدة.',None),('inference','لماذا يعد تسجيل «عدم الرؤية» مهمًا؟','لأنه يعطي معلومات عن زيارات لم تنتج صورة بدل جعل البيانات تتكون من المشاهدات الناجحة فقط.',None),('cause_effect','كيف تغير الباحثة المرحلة الثانية؟','تحدد مواقع وأوقاتًا مسبقًا وتجعل التسجيل منتظمًا، فيصبح السؤال عن المقارنة أكثر قابلية للإجابة.',None),('main_claim','ما العلاقة بين حجم البيانات وجودتها؟','الحجم الكبير لا يعوض تلقائيًا عن طريقة جمع منحازة أو غير متوازنة.',None),('argument_relation','لماذا يحتفظ الفريق بالبيانات الأولى؟','لأنها مفيدة لاكتشاف أماكن وأسئلة حتى إن لم تكن مناسبة لتقدير الانتشار بدقة.',None),('contrast','ما الفرق بين المرحلة الأولى والثانية؟','الأولى مشاركة مفتوحة كثيرة وغير متوازنة، والثانية مراقبة منظمة في مواقع وأوقات محددة.',None),('reference_resolution','إلى ماذا تشير «طريقة جمعها»؟','إلى الطريقة التي التقط بها السكان الصور واختاروا الأماكن والأوقات والأنواع.',None),('single_word_definition','ما معنى «معدات»؟','أدوات وأجهزة تستخدم لإنجاز عمل أو تجربة.', ['ar-r1371']),('single_word_definition','ما معنى «مراقبة» هنا؟','متابعة منظمة لما يحدث أو يظهر عبر وقت أو أماكن مختلفة.', ['ar-r1401'])]},
{'id':'ar-b2-u01-p03','sequence':3,'title':'من يستحق المورد المحدود؟','passage_type':'interleaved','genre':'science-policy case','domains':['science','public','education'],'topics':['research funding','resource allocation','criteria'],'text':'كان لدى مؤسسة تعليمية خيالية مورد مالي يكفي لدعم مشروعين بحثيين فقط من خمسة مقترحات. اقترح عضو في اللجنة إعطاء التمويل للمشروعين اللذين يتوقعان أكبر نتيجة مباشرة. اعترضت عضوة أخرى قائلة إن بعض المشروعات عالية المخاطرة قد لا تنتج نتيجة سريعة لكنها تفتح مجالًا جديدًا إذا نجحت. ظهر خلاف آخر حول منفعة المجتمع: هل الأفضل تمويل سؤال علمي أساسي قد يفيد لاحقًا، أم مشروع يختبر حلًا لمشكلة حالية؟ لم تحاول اللجنة العثور على مقياس واحد يحول الاختيارات إلى ترتيب آلي. كتبت بدلًا من ذلك معايير معلنة: جودة السؤال والطريقة، حجم المورد المطلوب، إمكانية التعلم حتى إذا لم تنجح الفرضية، القيمة العامة المحتملة، وما إذا كان هناك مصدر تمويل بديل. ثم طلبت من المراجعين شرح سبب الدرجة لا كتابة رقم فقط. أدى ذلك إلى بقاء الخلاف في مشروعين، لكنه جعل الخلاف أوضح: أحد الطرفين يعطي وزنًا أكبر للفائدة القريبة، والآخر لقيمة المعرفة واحتمال الفائدة البعيدة. قالت نور إن قرار التمويل لا يصبح «علميًا بحتًا» لمجرد أن موضوعه علم. الأدلة تخبرنا بما نعرفه عن كل مشروع، لكن توزيع المورد يتضمن أيضًا حكمًا على القيم والأولويات تحت عدم يقين.','target_forms':['مورد','تمويل'],'reviews':[{'id':'ar-r1272','form':'توزيع','review_stage':'R3','representation':'running_text'},{'id':'ar-r1290','form':'تقييم','review_stage':'R3','representation':'other'}],'grammar':[{'id':'ar-b2-evidence-values','role':'new','description':'الأدلة تخبرنا... لكن التوزيع يتضمن حكمًا على القيم والأولويات'}],'discourse':[{'id':'b2-science-funding-values','role':'new','description':'separate evidence about proposals from value judgments required to allocate scarce research resources'}],'qa':[('gist','لماذا لا تستخدم اللجنة معيارًا واحدًا؟','لأن المشروعات تختلف في المخاطرة والزمن والمنفعة والتعلم، والاختيار يتضمن قيمًا متعددة.',None),('literal_detail','اذكر ثلاثة معايير تضعها اللجنة.','جودة السؤال والطريقة، حجم المورد، إمكانية التعلم، القيمة العامة، أو وجود تمويل بديل.',None),('inference','لماذا يظل خلاف رغم وجود معايير معلنة؟','لأن الأطراف قد تعطي المعايير نفسها أوزانًا مختلفة تبعًا للأولويات.',None),('cause_effect','ما فائدة طلب شرح الدرجة؟','يكشف سبب التقييم والقيمة التي تقف وراءه بدل إخفاء الحكم داخل رقم.',None),('main_claim','لماذا ليس قرار التمويل «علميًا بحتًا»؟','لأن الأدلة لا تحدد وحدها وزن الفائدة القريبة مقابل المعرفة البعيدة أو المخاطرة.',None),('argument_relation','ما وظيفة ذكر المشروع عالي المخاطرة؟','يقدم مثالًا مضادًا لقاعدة اختيار أكبر نتيجة متوقعة مباشرة فقط.',None),('contrast','ما الفرق بين تقييم المشروع وتوزيع التمويل؟','التقييم يصف الجودة والاحتمالات، والتوزيع يقرر كيف تستخدم موارد محدودة وفق أولويات.',None),('reference_resolution','إلى ماذا تشير «ذلك» في «أدى ذلك إلى بقاء الخلاف»؟','إلى اعتماد المعايير وطلب تفسير الدرجات بدل الأرقام وحدها.',None),('single_word_definition','ما معنى «مورد» هنا؟','شيء محدود يمكن استخدامه لتحقيق غرض، مثل المال أو الوقت أو المعدات.', ['ar-r1374']),('single_word_definition','ما معنى «تمويل»؟','توفير المال اللازم لمشروع أو نشاط.', ['ar-r1402'])]},
{'id':'ar-b2-u01-p04','sequence':4,'title':'كمية أكبر أم احتمال أهم؟','passage_type':'transfer','genre':'paired-viewpoint analysis','domains':['science','public'],'topics':['risk communication','quantity','possibility'],'text':'ناقش نصان خياليان كيف ينبغي للناس فهم خطر علمي منخفض الاحتمال. ركز النص الأول على الكمية المتوقعة من الضرر إذا وقع الحدث، وقال إن النتيجة المحتملة كبيرة بما يكفي لتبرير الاستعداد حتى عندما يكون الاحتمال صغيرًا. ركز النص الثاني على إمكانية المبالغة في الخوف عندما يسمع الجمهور وصفًا دراميًا من غير معرفة الاحتمال نفسه، وحذر من إنفاق موارد ضخمة على سيناريو نادر على حساب مشكلات أكثر تكرارًا. لم يكن النصان يتحدثان عن رقمين متعارضين؛ كانا يعطيان وزنين مختلفين لعنصرين من الخطر: احتمال الحدث وحجم أثره. طلب المعلم من الطلاب تجنب سؤال «أي نص صحيح؟» في البداية، وأن يعيدوا بناء منطق كل واحد. الأول يخشى أن يؤدي التركيز على الاحتمال وحده إلى تجاهل أثر شديد، والثاني يخشى أن يؤدي التركيز على الأثر وحده إلى تجاهل ندرة الحدث وتكلفة الاستعداد. بعد ذلك صار الخلاف أكثر دقة: ما مقدار الاستعداد المعقول عندما توجد إمكانية لنتيجة كبيرة لكن الأدلة على احتمالها محدودة؟ قالت نور إن لغة الخطر تحتاج إلى حمل الكمية والاحتمال معًا، وإلى إعلان ما لا نعرفه بدل تحويل عدم اليقين إلى طمأنينة أو خوف مؤكد.','target_forms':['كمية','إمكانية'],'reviews':[{'id':'ar-r729','form':'خطر','review_stage':'R4','representation':'running_text'},{'id':'ar-r1349','form':'توقع','review_stage':'R3','representation':'other'}],'grammar':[{'id':'ar-b2-risk-two-dimensions','role':'new','description':'احتمال الحدث وحجم الأثر عنصران مختلفان في وصف الخطر'}],'discourse':[{'id':'b2-risk-viewpoint-reconstruction','role':'new','description':'reconstruct paired risk arguments before judging the trade-off under uncertainty'}],'qa':[('gist','ما سبب اختلاف النصين؟','يعطي أحدهما وزنًا أكبر لحجم الضرر المحتمل والآخر لاحتمال الحدث وتكلفة الاستعداد.',None),('literal_detail','ما الذي يحذر منه النص الثاني؟','الخوف المبالغ فيه وإنفاق موارد كبيرة على سيناريو نادر على حساب مشكلات متكررة.',None),('inference','لماذا يطلب المعلم عدم البدء بسؤال «أي نص صحيح»؟','لأن فهم بنية الحجة والقيمة التي يركز عليها كل نص ضروري قبل المقارنة والحكم.',None),('cause_effect','كيف تتغير طبيعة الخلاف بعد إعادة بناء الحجتين؟','ينتقل من اختيار نص إلى سؤال أدق عن مقدار الاستعداد تحت احتمال غير مؤكد وأثر كبير.',None),('main_claim','ما الذي تحتاج إليه لغة الخطر الجيدة؟','عرض حجم الأثر واحتمال وقوعه وعدم اليقين في كليهما بدل إبراز عنصر واحد فقط.',None),('argument_relation','ما وظيفة ذكر تكلفة الاستعداد؟','يضيف أثر القرار الوقائي نفسه إلى المقارنة بدل افتراض أن الاحتياط بلا تكلفة.',None),('contrast','ما الفرق بين احتمال الحدث وكمية الضرر؟','الأول يصف مدى إمكانية وقوعه، والثاني يصف حجم الأثر إذا وقع.',None),('reference_resolution','إلى ماذا تشير «الأول» و«الثاني» في الفقرة الوسطى؟','إلى النصين أو الموقفين المختلفين في تحليل الخطر.',None),('single_word_definition','ما معنى «كمية»؟','مقدار شيء يمكن التعبير عنه بعدد أو حجم أو قيمة.', ['ar-r1396']),('single_word_definition','ما معنى «إمكانية»؟','كون شيء ممكنًا أو قابلًا للحدوث أو التنفيذ.', ['ar-r1394'])]},
{'id':'ar-b2-u01-p05','sequence':5,'title':'مبدأ الشفافية لا يعني نشر كل شيء فورًا','passage_type':'integration','genre':'science-communication argument','domains':['science','media','society'],'topics':['transparency','preliminary findings','public communication'],'text':'اختلف فريق خيالي حول كيفية إعلان نتيجة أولية لدراسة ما زالت قيد المراجعة. قال طرف إن مبدأ الشفافية يقتضي نشر كل النتائج فور ظهورها، لأن تأخير المعلومات قد يجعل المؤسسة تبدو وكأنها تخفي ما لا يعجبها. ورد طرف آخر بأن النشر السريع قد يجعل رقمًا غير مستقر ينتشر خارج سياقه، خصوصًا إذا لم تكتمل فحوص الأخطاء بعد. بعد مناقشة طويلة اتفقوا على أن الشفافية ليست مرادفًا للسرعة وحدها. قرروا نشر ملخص يوضح السؤال والطريقة والنتيجة الأولية، مع تمييز واضح بين ما انتهى تحليله وما ما زال تحت الفحص. كما نشروا قائمة بالتغييرات إذا عدلت الأرقام لاحقًا، بدل استبدال النسخة القديمة بصمت. كان المبدأ الذي حاولوا حمايته هو قدرة القارئ على معرفة حالة الدليل وتاريخ تغيره. قالت نور إن المجتمع يحتاج إلى الوصول إلى المعلومات العلمية، لكنه يحتاج أيضًا إلى معرفة درجة استقرارها. وقد يكون الإفصاح عن عدم اليقين أكثر شفافية من تقديم رقم مبكر بصيغة نهائية. في المقابل، لا يجوز استخدام عبارة «ما زال أوليًا» بلا نهاية لتجنب نشر معلومات أصبحت قوية بما يكفي للنقاش العام. لذلك ترتبط الشفافية أيضًا بقواعد معلنة تحدد متى ينشر التحديث ولماذا يتأخر.','target_forms':['مبدأ'],'reviews':[{'id':'ar-r1333','form':'وثيقة','review_stage':'R3','representation':'other'},{'id':'ar-r1120','form':'إعلامي','review_stage':'R3','representation':'other'},{'id':'ar-r1156','form':'تفسير','review_stage':'R4','representation':'other'}],'grammar':[{'id':'ar-b2-principle-not-single-action','role':'new','description':'المبدأ ليس مرادفًا لفعل واحد مثل السرعة؛ يجب ربطه بالغرض والقواعد'}],'discourse':[{'id':'b2-science-transparency','role':'new','description':'balance timely disclosure with uncertainty labeling, revision history, and explicit publication rules'}],'qa':[('gist','ما الخلاف حول الشفافية؟','هل تعني نشر النتيجة الأولية فورًا أم يمكن تأخيرها قليلًا حتى توضح حالتها وتفحص الأخطاء.',None),('literal_detail','ما الذي ينشره الفريق مع النتيجة الأولية؟','السؤال والطريقة وحالة التحليل وقائمة تغييرات لاحقة إذا عدلت الأرقام.',None),('inference','لماذا يعد الاحتفاظ بتاريخ التغييرات مهمًا؟','لأنه يسمح للقارئ بمعرفة كيف تغير الدليل بدل رؤية نسخة نهائية بلا سياق زمني.',None),('cause_effect','كيف يحل الفريق التعارض بين السرعة والاستقرار؟','ينشر مبكرًا لكن بعلامات واضحة لعدم اليقين وقواعد للتحديث والتعديل.',None),('main_claim','كيف يعرف النص الشفافية العلمية؟','إتاحة المعلومات مع إظهار حالتها وحدودها وتاريخ تغيرها وفق قواعد معلنة، لا السرعة وحدها.',None),('argument_relation','لماذا يحذر النص من استخدام «ما زال أوليًا» بلا نهاية؟','حتى لا تتحول الحيطة إلى وسيلة دائمة لمنع معلومات ناضجة من النقاش العام.',None),('contrast','ما الفرق بين رقم أولي معلن بوضوح ورقم أولي مقدم كنهائي؟','الأول يحمل وصفًا لعدم اليقين وقابلية التعديل، والثاني يوحي بدرجة ثبات لم يكتسبها الدليل.',None),('reference_resolution','إلى ماذا تشير «المبدأ الذي حاولوا حمايته»؟','إلى الشفافية بوصفها قدرة القارئ على معرفة حالة الدليل وتغيره.',None),('single_word_definition','ما معنى «مبدأ»؟','قاعدة أو قيمة عامة توجه طريقة التفكير أو اتخاذ القرار.', ['ar-r1387']),('inference','لماذا يمكن لإعلان عدم اليقين أن يزيد الثقة بدل أن يضعفها؟','لأنه يطابق لغة المؤسسة مع الحالة الحقيقية للدليل ويجعل التغير المتوقع مفهومًا مسبقًا.',None)]},
{'id':'ar-b2-u01-p06','sequence':6,'title':'العلم لا ينتهي عند النتيجة','passage_type':'fluency','genre':'B2 science-society synthesis','domains':['science','society','education'],'topics':['models','observation','funding','risk','communication'],'text':'في نهاية الوحدة رأت نور أن أصعب أسئلة العلم والمجتمع لا تبدأ دائمًا من خلاف على حقيقة واحدة. أحيانًا يكون الاتفاق على البيانات واسعًا، بينما يختلف الناس في معنى تطبيقها. النموذج قد يوضح بنية علاقة لكنه لا يمثل كل الواقع. مشروع المراقبة قد ينتج كمية ضخمة من الملاحظات، لكن طريقة الجمع تحدد السؤال الذي تستطيع البيانات الإجابة عنه. لجنة التمويل قد تتفق على جودة مشروعين ثم تختلف في المبدأ الذي يعطي الأولوية للفائدة القريبة أو للمعرفة بعيدة المدى. وفي حديث الخطر يجب جمع إمكانية الحدث مع حجم أثره وتكلفة الاستعداد له. حتى الشفافية العلمية لا تتحول آليًا إلى قاعدة «انشر فورًا»؛ تحتاج إلى طريقة تظهر حالة النتيجة وتاريخ مراجعتها. لذلك بدأت نور تفصل بين ثلاث طبقات عند قراءة نقاش علمي عام: ما الذي تقوله الأدلة؟ ما الذي لا تقوله بعد؟ وما القيم أو القرارات التي تدخل عندما ننتقل من المعرفة إلى الفعل؟ هذا الفصل لا يجعل القرار سهلًا، لكنه يمنع خلط الخلاف العلمي بالخلاف على الأولويات. قالت إن العلم مهم للمجتمع ليس لأنه يلغي الحكم البشري، بل لأنه يجعل بعض أجزاء الحكم قابلة للفحص والتصحيح، ويجبرنا على أن نوضح أين ينتهي الدليل وأين يبدأ الاختيار.','target_forms':[],'reviews':[{'id':'ar-r1271','form':'باحث','review_stage':'R2','representation':'other'},{'id':'ar-r1373','form':'بنية','review_stage':'R2','representation':'running_text'},{'id':'ar-r1371','form':'معدات','review_stage':'R2','representation':'other'},{'id':'ar-r1379','form':'حشرة','review_stage':'R2','representation':'other'},{'id':'ar-r1401','form':'مراقبة','review_stage':'R2','representation':'running_text'},{'id':'ar-r1374','form':'مورد','review_stage':'R2','representation':'other'},{'id':'ar-r1402','form':'تمويل','review_stage':'R2','representation':'running_text'},{'id':'ar-r1396','form':'كمية','review_stage':'R2','representation':'running_text'},{'id':'ar-r1394','form':'إمكانية','review_stage':'R2','representation':'running_text'},{'id':'ar-r1387','form':'مبدأ','review_stage':'R2','representation':'running_text'}],'grammar':[{'id':'ar-b2-u01-cumulative','role':'integration','description':'separate evidence, uncertainty, values, and decisions in science-society arguments'}],'discourse':[{'id':'b2-science-society-synthesis','role':'integration','description':'synthesize model limits, sampling, allocation, risk, and transparency into a layered evidence-to-action framework'}],'qa':[('gist','ما الطبقات الثلاث التي تفصلها نور؟','ما تقوله الأدلة، وما لا تقوله بعد، والقيم أو القرارات التي تدخل عند الانتقال إلى الفعل.',None),('literal_detail','ما الحد المذكور في مشروع المراقبة؟','طريقة جمع الملاحظات تحدد السؤال الذي يمكن للبيانات الإجابة عنه.',None),('inference','لماذا قد يختلف الناس رغم اتفاقهم على البيانات؟','لأن تطبيق البيانات يحتاج إلى أوزان للقيم والمخاطر والأولويات لا تحددها البيانات وحدها.',None),('cause_effect','ما فائدة الفصل بين الدليل والاختيار؟','يمنع وصف خلاف على الأولويات كأنه خلاف علمي على الوقائع نفسها.',None),('main_claim','كيف يصف النص دور العلم في القرار الاجتماعي؟','يجعل أجزاء من الحكم قابلة للفحص والتصحيح ويحدد ما يدعمه الدليل، لكنه لا يلغي الاختيارات القيمية.',None),('argument_relation','لماذا يجمع النص خمسة أمثلة مختلفة؟','ليظهر أن الانتقال من معرفة علمية إلى قرار اجتماعي يتكرر فيه فصل الدليل والحدود والقيم.',None),('contrast','ما الفرق بين الخلاف العلمي والخلاف على الأولويات؟','الأول يتعلق بما تدعمه الأدلة أو تفسيرها، والثاني بوزن أهداف وقيم مختلفة عند القرار.',None),('reference_resolution','إلى ماذا تشير «هذا الفصل»؟','إلى فصل ما تقوله الأدلة وما لا تقوله وما يضاف من قيم وقرارات.',None),('summary','اذكر أربعة حدود أو مفاضلات من الوحدة.','حدود النموذج، انحياز جمع الملاحظات، أولوية التمويل، الاحتمال مقابل حجم الأثر، والسرعة مقابل استقرار النتيجة.',None),('inference','لماذا لا يعد الاعتراف ببداية «الاختيار» هزيمة للعلم؟','لأنه يوضح دور العلم بدقة ويمنع استخدامه لتغطية أحكام قيمية لا تنتج منه مباشرة.',None)]}
]
